package com.householdfinance.finance.domain; import java.time.*;import java.util.*;public final class Household{private final HouseholdId id;private String name;private final Instant createdAt;private Instant updatedAt;private final List<HouseholdMember> members;private Household(HouseholdId i,String n,Instant c,List<HouseholdMember>m){id=i;name=valid(n);createdAt=c;updatedAt=c;members=new ArrayList<>(m);}public static Household create(String n,UUID owner,Instant now){var h=new Household(HouseholdId.newId(),n,now,List.of());h.members.add(new HouseholdMember(owner,MemberRole.ADMIN));return h;}public static Household rehydrate(UUID id,String n,Instant created,Instant updated,List<HouseholdMember> members){var household=new Household(new HouseholdId(id),n,created,members);household.updatedAt=updated;return household;}private static String valid(String n){if(n==null||n.isBlank())throw new DomainException("Household name is required");return n.trim();}private HouseholdMember find(UUID u){return members.stream().filter(m->m.userId().equals(u)).findFirst().orElse(null);}public void requireActiveMember(UUID u){if(find(u)==null||!find(u).active())throw new DomainException("Active household membership required");}public void requireAdmin(UUID u){if(find(u)==null||!find(u).admin())throw new DomainException("Household administrator authorization required");}public void rename(String n,UUID u,Instant now){requireAdmin(u);name=valid(n);updatedAt=now;}public void addMember(UUID a,UUID u,MemberRole r,Instant now){requireAdmin(a);if(find(u)!=null)throw new DomainException("User already belongs to household");members.add(new HouseholdMember(u,r));updatedAt=now;}public void removeMember(UUID a,UUID u,Instant now){requireAdmin(a);var m=find(u);if(m==null)throw new DomainException("Member not found");if(m.admin()&&members.stream().filter(HouseholdMember::admin).count()==1)throw new DomainException("Cannot remove the last administrator");m.deactivate();updatedAt=now;}public HouseholdId id(){return id;}public String name(){return name;}public Instant createdAt(){return createdAt;}public Instant updatedAt(){return updatedAt;}public List<HouseholdMember> members(){return List.copyOf(members);}}
